import Page7 from './pages/Page7.jsx';
import Page8 from './pages/Page8.jsx';
import Page9 from './pages/Page9.jsx';
import Page10 from './pages/Page10.jsx';
import Page11 from './pages/Page11.jsx';
const pages={"demo-automation-1":Page0,"demo-automation-1-agents":Page1,"demo-automation-1-changelog":Page2,"demo-automation-1-contact":Page3,"demo-automation-1-customer-story":Page4,"demo-automation-1-customers":Page5,"demo-automation-1-integrations":Page6,"demo-automation-1-platform":Page7,"demo-automation-1-pricing":Page8,"demo-automation-1-security":Page9,"demo-automation-1-solutions":Page10,"demo-automation-1-templates":Page11};
export default function App(){
const [page,setPage]=useState(()=>new URLSearchParams(location.hash.slice(1)).get('page')||"demo-automation-1");
useEffect(()=>{const change=()=>setPage(new URLSearchParams(location.hash.slice(1)).get('page')||"demo-automation-1");const navigate=e=>{const a=e.target.closest('a[href]');const href=a?.getAttribute('href');if(!href?.startsWith('#page='))return;const next=new URLSearchParams(href.slice(1)).get('page');if(!pages[next])return;e.preventDefault();e.stopPropagation();setPage(next);try{if(location.protocol!=='about:')history.pushState(null,'',href)}catch{}};document.addEventListener('click',navigate,true);window.addEventListener('hashchange',change);window.addEventListener('popstate',change);return()=>{document.removeEventListener('click',navigate,true);window.removeEventListener('hashchange',change);window.removeEventListener('popstate',change)}},[]);
useTemplateRuntime(page);const Page=pages[page]||Page0;return <div id='template-page' key={page}><Page/></div>;
}

